func TestE2E_AutoCommitStrategy(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t, "auto-commit")

	// 1. Agent creates a file
	t.Log("Step 1: Agent creating file with auto-commit strategy")
