// isTrivialLine returns true for lines that are likely structural boilerplate
// rather than meaningful content. Uses a language-agnostic heuristic based on
// alphanumeric character ratio - lines that are mostly punctuation/symbols
// (like `});`, `])`, `{`) are considered trivial.
func isTrivialLine(line string) bool {
	if len(line) == 0 {
		return true
	}

	// Count alphanumeric characters
	alphanumeric := 0
	for i := 0; i < len(line); i++ {
