// TestExtractSignificantLines tests the full line extraction pipeline.
func TestExtractSignificantLines(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		content  string
		wantKeys []string // lines that should be in the result
		wantNot  []string // lines that should NOT be in the result
	}{
		{
			name: "go function",
			content: `package main

func hello() {
	fmt.Println("hello world")
	return
}`,
			wantKeys: []string{
				`fmt.Println("hello world")`,
			},
			wantNot: []string{
				"package main",
				"func hello() {",
				"}",
				"return",
			},
		},
		{
			name: "python function",
			content: `def calculate(x, y):
    result = x + y
    print(f"Result: {result}")
    return result`,
			wantKeys: []string{
				"result = x + y",
				`print(f"Result: {result}")`,
				"return result",
			},
			wantNot: []string{
				"def calculate(x, y):",
			},
		},
		{
			name: "javascript",
			content: `const handler = async (req) => {
  const data = await fetch(url);
  return data.json();
};`,
			wantKeys: []string{
				"const data = await fetch(url);",
				"return data.json();",
			},
			wantNot: []string{
				"};",
			},
		},
		{
			name: "short lines filtered",
			content: `a = 1
b = 2
longVariableName = 42`,
			wantKeys: []string{
				"longVariableName = 42",
			},
			wantNot: []string{
				"a = 1", // too short (< 10 chars)
				"b = 2",
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			result := extractSignificantLines(tt.content)

			for _, want := range tt.wantKeys {
				if !result[want] {
					t.Errorf("extractSignificantLines() missing expected line: %q", want)
				}
			}

			for _, notWant := range tt.wantNot {
				if result[notWant] {
					t.Errorf("extractSignificantLines() should not contain: %q", notWant)
				}
			}
		})
	}
}

